from test_bufftap import test, ROOT
B="local B=BuffTap; "
test('Blacklist sharing defaults off without migrating local entries',B+"B:SetBlocked('player','Ally',true); assert(not B:BlacklistAccountWide()); assert(B.db.blockedPlayers.ally and B:BlacklistStore('player')==B.db.blockedPlayers)")
test('Enabling shared blacklist seeds both lists without aliasing originals',B+"B:SetBlocked('player','Ally',true); B:SetBlocked('guild','Test Guild',true); assert(B:SetBlacklistAccountWide(true)); assert(B:BlacklistStore('player').ally and B:BlacklistStore('guild')['test guild']); assert(B:BlacklistStore('player')~=B.db.blockedPlayers); B:SetBlocked('player','Ally',false); assert(not B:BlacklistStore('player').ally and B.db.blockedPlayers.ally)")
test('Disabling sharing restores profile list and retains account list',B+"B:SetBlocked('player','Local',true); B:SetBlacklistAccountWide(true); B:SetBlocked('player','Account',true); assert(B:SetBlacklistAccountWide(false)); assert(B:BlacklistStore('player')['local'] and not B:BlacklistStore('player').account); assert(B:AccountBlacklist().players.account)")
for cls in ('DRUID','MAGE','PRIEST','PALADIN','WARRIOR','HUNTER','SHAMAN','WARLOCK','ROGUE'):
 test('Shared blacklist follows profile and class '+cls,B+"B:SetBlacklistAccountWide(true); B:SetBlocked('player','Ally',true); B:SetBlocked('guild','Shared Guild',true); B:CreateSettingsProfile('Another',false); playerClass='"+cls+"'; B:InitDB(); assert(B:BlacklistAccountWide() and B:BlockReason('target')=='blacklisted player'); assert(B:BlacklistStore('guild')['shared guild']); assert(not B.db.blockedPlayers.ally)")
SOURCE=B+"local original=B.profileDB:GetCurrentProfile(); B:SetBlocked('player','Ally',true); B:SetBlocked('guild','Source Guild',true); local before=B.db.seconds; B:CreateSettingsProfile('Source',true); B.db.seconds=123; B:SetBlocked('player','SourceOnly',true); B:SelectSettingsProfile(original); "
test('Copy blacklist merges duplicates without copying unrelated settings',SOURCE+"B:SetBlocked('player','KeepMe',true); local beforeCopy=B.db.seconds; local ok,n=B:CopyBlacklistFromProfile('Source'); assert(ok and n==1); assert(B.db.seconds==beforeCopy and B.db.blockedPlayers.keepme and B.db.blockedPlayers.sourceonly); assert(B.profileDB.sv.profiles.Source.blockedPlayers.sourceonly); assert(B.profileDB.sv.profiles.Source.blockedPlayers.keepme==nil)")
test('Copy into account scope preserves profile lists',SOURCE+"B:SetBlacklistAccountWide(true); local localList=B.db.blockedPlayers; local ok,n=B:CopyBlacklistFromProfile('Source'); assert(ok and n==1 and B:BlacklistStore('player').sourceonly); assert(not localList.sourceonly)")
test('Copy rejects missing and active profiles',B+"assert(not B:CopyBlacklistFromProfile('missing')); assert(not B:CopyBlacklistFromProfile(B.profileDB:GetCurrentProfile()))")
test('Copy sanitizes names without modifying source data',B+"B.profileDB.sv.profiles.Source={blockedPlayers={[' Ally ']=true,['bad|name']=true,['']=true,[5]=true,ignored=false},blockedGuilds={[' Guild ']=true}}; local ok,n=B:CopyBlacklistFromProfile('Source'); assert(ok and n==2 and B.db.blockedPlayers.ally and B.db.blockedGuilds.guild); assert(B.profileDB.sv.profiles.Source.blockedPlayers[' Ally '])")
test('Account data sanitizes malformed persisted names',B+"B.profileDB.global.accountBlacklist={enabled=true,players={[' Ally ']=true,['bad|name']=true},guilds='bad'}; assert(B:BlockReason('target')=='blacklisted player'); assert(not B:BlacklistStore('player')['bad|name'] and type(B:BlacklistStore('guild'))=='table')")
test('Sharing mutations remain combat guarded',SOURCE+"combat=true; assert(not B:SetBlacklistAccountWide(true)); assert(not B:CopyBlacklistFromProfile('Source')); assert(not B:MergeBlacklist('player',{combat=true})); assert(not B:SetBlocked('player','Combat',true)); assert(not B:BlacklistAccountWide() and not B.db.blockedPlayers.combat)")
test('Sharing keeps per-profile instance rule',B+"B:SetBlacklistAccountWide(true); B:SetBlocked('player','Ally',true); B.InGroupInstance=function() return true end; B.db.blacklistInInstances=false; assert(not B:BlockReason('target')); B.db.blacklistInInstances=true; assert(B:BlockReason('target')=='blacklisted player')")
test('Full exports use active account list and private exports omit names',B+"B:SetBlocked('player','HiddenLocalName',true); B:SetBlacklistAccountWide(true); B:SetBlocked('player','OnlyAccountName',true); B:SetBlocked('guild','OnlyAccountGuild',true); local safe=B:ExportSettings(true):lower(); assert(not safe:find('onlyaccount',1,true) and not safe:find('hiddenlocalname',1,true)); local full=B:ExportSettings(false):lower(); assert(full:find('onlyaccountname',1,true) and full:find('onlyaccountguild',1,true)); assert(not full:find('accountBlacklist',1,true))")
test('Explicit settings import merges active list without changing account scope',B+"B:SetBlocked('player','Imported',true); local export=B:ExportSettings(false); B.db.blockedPlayers={}; B:SetBlacklistAccountWide(true); B:SetBlocked('player','KeepAccount',true); assert(B:ImportSettings(export)); assert(B:BlacklistAccountWide() and B:BlacklistStore('player').imported and B:BlacklistStore('player').keepaccount); assert(not B.db.blockedPlayers.imported)")
test('Resetting a profile does not reset the shared blacklist',B+"B:SetBlacklistAccountWide(true); B:SetBlocked('player','Ally',true); assert(B:ResetSettingsProfile()); assert(B:BlacklistAccountWide() and B:BlockReason('target')=='blacklisted player')")
test('Blocking account name disarms a prepared friendly target cast',B+"B.db.group=false; B.db.friendlyTarget=true; B.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild'); refresh(); assert(B.action and B.action.target=='target','initial '..tostring(B.action and B.action.target)..' '..tostring(B.action and B.action.key)); B:SetBlacklistAccountWide(true); B:SetBlocked('player','Ally',true); B.button.scripts.PreClick(nil,'LeftButton',false); assert(not B.action and not B.button.attrs.type1,'after block '..tostring(B.action and B.action.target)..' '..tostring(B.action and B.action.key))")
RECORD=(ROOT/'tests/nearby_preview_record.lua').read_text(encoding='utf-8-sig')
test('Blacklist controls enable profile copy immediately',RECORD+SOURCE+"B:ShowBlacklist(); local f=B.options; assert(not f.blackCopy.enabled); f.blackSource.scripts.OnClick(f.blackSource); local found; for _,row in ipairs(f.blackSource.menu.rows) do if row.choice=='Source' then row.scripts.OnClick(row); found=true; break end end; assert(found and f.blackCopy.enabled); f.blackCopy.scripts.OnClick(); assert(B.db.blockedPlayers.sourceonly); f.blackShared:SetChecked(true); f.blackShared.scripts.OnClick(f.blackShared); assert(B:BlacklistAccountWide() and f.blackShared:GetChecked()); for _,l in ipairs(f.blackLists) do assert(l.scroll.__draw.h==208) end; assert(f.blackScopeHint.__draw.points[1][3]==-238)")

